// BestHand returns the winning hand(s) from the list of hands,
// preserving the order in which they appear.
// It returns an error if any hand is malformed.
func BestHand(hands []string) ([]string, error) {
	if len(hands) == 0 {
		return nil, errors.New("no hands to compare")
	}

	scores := make([]score, len(hands))
	for i, s := range hands {
		h, err := parseHand(s)
		if err != nil {
			return nil, err
		}
		scores[i] = h.evaluate()
	}

	best := 0
	for i := 1; i < len(hands); i++ {
		if scores[i].less(scores[best]) {
			best = i
		}
	}

	winners := make([]string, 0, len(hands))
	for i, s := range scores {
		if s.equal(scores[best]) {
			winners = append(winners, hands[i])
		}
	}
	return winners, nil
}

